const BUDGET = 1000;

// Each node: { cost, first?, children? }
// list nodes carry a `first` multiplier; leaf/scalar nodes omit it.
function nodeCost(node) {
  const own = node.cost || 0;
  const childSum = (node.children || []).reduce((s, c) => s + nodeCost(c), 0);
  const mult = node.first || 1;
  return (own + childSum) * mult;
}

function evaluate(name, root) {
  const cost = nodeCost(root);
  const verdict = cost > BUDGET ? 'REJECT' : 'ACCEPT';
  console.log(name + ': cost=' + cost + ' -> ' + verdict);
}

// Query A: viewer { profile { email } }  — cheap, no list fan-out
const queryA = { cost: 1, children: [
  { cost: 1, children: [ { cost: 1 } ] }
] };

// Query B: users(first:100){ posts(first:100){ comments(first:100){ body } } }
const queryB = { cost: 1, first: 100, children: [
  { cost: 1, first: 100, children: [
    { cost: 1, first: 100, children: [ { cost: 1 } ] }
  ] }
] };

evaluate('A', queryA);
evaluate('B', queryB);
